    app.use('*', cache({ cacheName: 'skip-test', wait: true }))
    app.get('/', (c) => {
      c.header('Set-Cookie', 'session=secret')
      return c.text('response')
    })

    await app.request('/')
    expect(putSpy).not.toHaveBeenCalled()
  })

