    const app = new Hono()
    app.use('*', cache({ cacheName: 'skip-test', wait: true }))
    app.get('/', (c) => {
      return c.text('response')
    })

    await app.request('/')
    // IMPORTANT: put() SHOULD be called for normal responses
    expect(putSpy).toHaveBeenCalled()
