describe('stale-while-revalidate', () => {
  class TrackingContext implements ExecutionContext {
    pending: Promise<unknown>[] = []
    passThroughOnException(): void {
      throw new Error('Method not implemented.')
    }
    waitUntil(promise: Promise<unknown>): void {
      this.pending.push(promise)
    }
    async flush() {
      const tasks = this.pending
      this.pending = []
      await Promise.all(tasks)
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    props: any
  }

  let mockCache: {
    match: ReturnType<typeof vi.fn>
    put: ReturnType<typeof vi.fn>
    keys: ReturnType<typeof vi.fn>
  }

  beforeEach(() => {
    const store = new Map<string | Request, Response>()
    mockCache = {
      match: vi.fn((key: string | Request) => Promise.resolve(store.get(key)?.clone())),
      put: vi.fn((key: string | Request, response: Response) => {
        store.set(key, response.clone())
        return Promise.resolve()
      }),
      keys: vi.fn(() => Promise.resolve(Array.from(store.keys()))),
    }
    vi.stubGlobal('caches', {
      open: vi.fn().mockResolvedValue(mockCache),
    })
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2026-01-01T00:00:00Z'))
  })

  afterEach(() => {
    vi.useRealTimers()
    vi.restoreAllMocks()
    vi.unstubAllGlobals()
  })

  const buildApp = (opts?: { swr?: number }) => {
    const app = new Hono()
    let count = 0
    app.use(
      '*',
      cache({
        cacheName: 'swr-test',
        cacheControl: 'max-age=10',
        staleWhileRevalidate: opts?.swr ?? 30,
      })
    )
    app.get('/', (c) => {
      count++
      c.header('X-Count', `${count}`)
      return c.text(`response ${count}`)
    })
    return { app, getCount: () => count }
  }

  it('Should return X-Cache-Status: MISS on the first request', async () => {
    const ctx = new TrackingContext()
    const { app, getCount } = buildApp()

    const res = await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()
    expect(res.headers.get('X-Cache-Status')).toBe('MISS')
    expect(await res.text()).toBe('response 1')
    expect(getCount()).toBe(1)
    expect(mockCache.put).toHaveBeenCalledOnce()
  })

  it('Should return X-Cache-Status: HIT for a fresh cached response', async () => {
    const ctx = new TrackingContext()
    const { app, getCount } = buildApp()

    await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()

    vi.setSystemTime(new Date('2026-01-01T00:00:05Z'))
    const res = await app.fetch(new Request('http://localhost/'), undefined, ctx)
    expect(res.headers.get('X-Cache-Status')).toBe('HIT')
    expect(res.headers.get('X-Count')).toBe('1')
    expect(await res.text()).toBe('response 1')
    expect(getCount()).toBe(1)
  })

  it('Should not leak X-Cache-Stored-At in the served response', async () => {
    const ctx = new TrackingContext()
    const { app } = buildApp()

    await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()

    vi.setSystemTime(new Date('2026-01-01T00:00:05Z'))
    const res = await app.fetch(new Request('http://localhost/'), undefined, ctx)
    expect(res.headers.get('X-Cache-Stored-At')).toBeNull()
  })

  it('Should serve STALE response and revalidate in background within SWR window', async () => {
    const ctx = new TrackingContext()
    const { app, getCount } = buildApp()

    await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()
    expect(getCount()).toBe(1)
    expect(mockCache.put).toHaveBeenCalledTimes(1)

    // Past max-age (10s) but within stale window (10 + 30 = 40s)
    vi.setSystemTime(new Date('2026-01-01T00:00:15Z'))
    const stale = await app.fetch(new Request('http://localhost/'), undefined, ctx)
    expect(stale.headers.get('X-Cache-Status')).toBe('STALE')
    expect(stale.headers.get('X-Count')).toBe('1')
    expect(await stale.text()).toBe('response 1')
    // Handler not yet invoked again because revalidation runs in waitUntil
    expect(getCount()).toBe(1)

    // Flush the background revalidation
    await ctx.flush()
    expect(getCount()).toBe(2)
    expect(mockCache.put).toHaveBeenCalledTimes(2)

    // Subsequent request returns the revalidated response as a HIT
    const fresh = await app.fetch(new Request('http://localhost/'), undefined, ctx)
    expect(fresh.headers.get('X-Cache-Status')).toBe('HIT')
    expect(fresh.headers.get('X-Count')).toBe('2')
    expect(await fresh.text()).toBe('response 2')
  })

  it('Should treat as MISS when cached response is beyond stale window', async () => {
    const ctx = new TrackingContext()
    const { app, getCount } = buildApp()

    await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()

    // Past max-age + SWR (10 + 30 = 40s)
    vi.setSystemTime(new Date('2026-01-01T00:01:00Z'))
    const res = await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()
    expect(res.headers.get('X-Cache-Status')).toBe('MISS')
    expect(res.headers.get('X-Count')).toBe('2')
    expect(await res.text()).toBe('response 2')
    expect(getCount()).toBe(2)
  })

  it('Should still apply shouldSkipCache during background revalidation', async () => {
    const ctx = new TrackingContext()
    const app = new Hono()
    let count = 0
    let skipNext = false
    app.use(
      '*',
      cache({
        cacheName: 'swr-skip-test',
        cacheControl: 'max-age=10',
        staleWhileRevalidate: 30,
      })
    )
    app.get('/', (c) => {
      count++
      c.header('X-Count', `${count}`)
      if (skipNext) {
        c.header('Cache-Control', 'no-store')
      }
      return c.text(`response ${count}`)
    })

    await app.fetch(new Request('http://localhost/'), undefined, ctx)
    await ctx.flush()
